struct MvShapeModelArrayData {std::atomic<std::size_t> refs{1};std::vector<MvShapeModel> values;};
MvShapeModelArray::MvShapeModelArray() noexcept=default;
MvShapeModelArray::MvShapeModelArray(const MvShapeModel* models,std::int64_t length) {
  if(length<0 || std::uint64_t(length)>std::uint64_t(std::numeric_limits<std::ptrdiff_t>::max())/sizeof(MvShapeModel) || (length && !models))throw MvException(MvStatus::InvalidArgument,MvErrorCode::InvalidValue,"MvShapeModelArray","models",-1,"nonnegative length and valid model array required");
  if(length){auto next=std::make_unique<MvShapeModelArrayData>();next->values.assign(models,models+length);data_=next.release();}
}
MvShapeModelArray::MvShapeModelArray(const MvShapeModelArray& other):data_(other.data_){if(data_)data_->refs.fetch_add(1,std::memory_order_relaxed);}
MvShapeModelArray::MvShapeModelArray(MvShapeModelArray&& other) noexcept:data_(std::exchange(other.data_,nullptr)){}
MvShapeModelArray& MvShapeModelArray::operator=(const MvShapeModelArray& other){if(this!=&other){auto next=other.data_;if(next)next->refs.fetch_add(1,std::memory_order_relaxed);Clear();data_=next;}return *this;}
MvShapeModelArray& MvShapeModelArray::operator=(MvShapeModelArray&& other) noexcept {if(this!=&other){Clear();data_=std::exchange(other.data_,nullptr);}return *this;}
MvShapeModelArray::~MvShapeModelArray() noexcept{Clear();}
void MvShapeModelArray::Clear() noexcept{auto old=std::exchange(data_,nullptr);if(old&&old->refs.fetch_sub(1,std::memory_order_acq_rel)==1)delete old;}
const MvShapeModel* MvShapeModelArray::Tools() const noexcept{return data_?data_->values.data():nullptr;}
std::int64_t MvShapeModelArray::Length() const noexcept{return data_?std::int64_t(data_->values.size()):0;}
void MvShapeModelArray::SetFromTuple(const MvTuple& handles) {
  if(!handles.Length()){Clear();return;}auto next=std::make_unique<MvShapeModelArrayData>();next->values.reserve(handles.Length());
  for(std::size_t i=0;i<handles.Length();++i)next->values.emplace_back(handles.H(i));Clear();data_=next.release();
}
MvTuple MvShapeModelArray::ConvertToTuple() const {MvTuple result;if(data_)for(const auto& model:data_->values)result.Append(model);return result;}

